<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';import {Download,RefreshCw,Pause,Play,X,Trash2,RotateCcw} from 'lucide-vue-next';import {useStudio,api} from '../store';import BrandSymbol from './BrandSymbol.vue';
const props=defineProps({embedded:Boolean});const s=useStudio(),open=ref(false),working=ref(false),uninstall=ref(false),keepModels=ref(true),keepWorks=ref(true),maintaining=ref(false);let timer,startup;
const status=computed(()=>s.updateStatus||{state:'idle',files:[],message:'尚未检查更新'}),bytes=n=>n>=1024**3?(n/1024**3).toFixed(2)+' GB':(n/1024**2).toFixed(1)+' MB';
async function check(){working.value=true;try{s.updateStatus=await api('updates/check',{});}finally{working.value=false;}}
async function download(){s.updateStatus=await api('updates/download',{});open.value=true;}
async function control(action){s.updateStatus=await api('updates/control',{action});}
function dismiss(){open.value=false;if(status.value.release)s.config.updateNoticeVersion=status.value.release.version;}
async function maintain(mode){if(maintaining.value)return;if(!window.desktop?.maintainInstallation)throw Error('请在桌面客户端使用此功能');maintaining.value=true;try{await window.__mogeFlush?.();await window.desktop.maintainInstallation({mode,keepModels:keepModels.value,keepWorks:keepWorks.value});}finally{maintaining.value=false;}}
watch(()=>status.value.release?.version,version=>{if(!props.embedded&&status.value.available&&version!==s.config.updateNoticeVersion)open.value=true;});
onMounted(async()=>{s.updateStatus=await api('updates/status');if(!props.embedded){startup=setTimeout(()=>{if(s.config.autoCheckUpdates!==false)void check().catch(()=>{});},20000);timer=setInterval(()=>{if(s.config.autoCheckUpdates!==false)void check().catch(()=>{});},6*60*60*1000);}});onUnmounted(()=>{clearTimeout(startup);clearInterval(timer);});
</script>
<template><section v-if="embedded" class="card"><div class="card-heading"><strong>更新与卸载</strong><span class="muted">当前 {{status.currentVersion||'0.1.0'}}</span></div><div class="settings-body"><label class="inline-check"><input type="checkbox" :checked="s.config.autoCheckUpdates!==false" @change="s.config.autoCheckUpdates=$event.target.checked"/>自动检查官方更新并提醒</label><p>{{status.message}}</p><p v-if="status.checkedAt" class="muted">最近检查：{{new Date(status.checkedAt).toLocaleString()}}</p><div class="button-row"><button class="secondary" :disabled="working||status.checking" @click="s.action(check)"><RefreshCw :size="16" :class="{spin:working||status.checking}"/>检查更新</button><button v-if="status.release" class="secondary" @click="open=true">查看更新公告与进度</button></div><p class="muted">更新来自官方发布页，自动适配当前网络。下载支持暂停、续传与重试；安装前校验全部程序文件，模型、图片、漫画和对话保留。源码开发版可检查更新，程序替换与卸载在正式整合包中执行。</p><div class="uninstall-section"><h3>卸载若水漫画</h3><p class="muted">可以保留模型及创作数据。卸载前会保存当前编辑，并检查是否有未完成的生成任务。</p><button class="secondary danger" @click="uninstall=true"><Trash2 :size="16"/>选择卸载内容…</button></div></div></section>
<div v-if="open" class="modal-backdrop update-backdrop"><section class="modal update-dialog" role="dialog" aria-modal="true" aria-label="若水漫画更新"><div class="modal-dismiss-row"><button class="icon-button" aria-label="关闭更新窗口" @click="dismiss"><X/></button></div><div class="modal-title"><h2>若水漫画 · 软件更新</h2></div><div class="update-hero"><div class="brand-mark"><BrandSymbol/></div><div><h2>{{status.release?.title||'检查软件更新'}}</h2><p>当前 {{status.currentVersion}}<span v-if="status.release"> → {{status.release.version}}</span></p><small>{{status.message}}</small></div></div><div class="update-release-notes">{{status.release?.notes||'发布者尚未提供更新公告。'}}</div><template v-if="status.files?.length"><div class="progress"><i :style="{width:(status.percent||0)+'%'}"/></div><p class="muted">总进度 {{status.percent||0}}%<span v-if="status.speed"> · {{bytes(status.speed)}}/s</span></p><div v-for="file in status.files" :key="file.name" class="local-file-row"><div><strong>{{file.name}}</strong><small>{{bytes(file.bytes||0)}} / {{file.size?bytes(file.size):'正在确认大小'}} · {{({waiting:'等待下载',running:'正在下载',paused:'已暂停',done:'已校验',cancelled:'已取消',error:'下载未完成'})[file.state]||file.state}}</small></div></div></template><div class="button-row"><button v-if="['available','current'].includes(status.state)&&status.available&&status.files.length" class="primary" @click="s.action(download)"><Download :size="17"/>下载更新</button><button v-if="status.state==='downloading'" class="secondary" @click="s.action(()=>control('pause'))"><Pause :size="16"/>暂停</button><button v-if="status.state==='paused'" class="primary" @click="s.action(()=>control('resume'))"><Play :size="16"/>继续</button><button v-if="['error','cancelled'].includes(status.state)" class="primary" @click="s.action(()=>control('retry'))"><RefreshCw :size="16"/>重试</button><button v-if="status.state==='ready'" class="primary" @click="s.action(()=>maintain('apply'))"><RotateCcw :size="17"/>安装更新并重启</button><button v-if="['downloading','paused'].includes(status.state)" class="quiet danger" @click="s.action(()=>control('cancel'))">取消下载</button><button class="quiet" @click="dismiss">稍后处理</button></div></section></div>
<div v-if="uninstall" class="modal-backdrop" @click.self="!maintaining&&(uninstall=false)"><section class="modal" role="dialog" aria-modal="true" aria-label="选择卸载内容"><div class="modal-dismiss-row"><button class="icon-button" aria-label="关闭卸载窗口" @click="uninstall=false"><X/></button></div><div class="modal-title"><h2>选择卸载内容</h2></div><div class="settings-body"><label class="inline-check"><input type="checkbox" v-model="keepModels"/>保留全部模型文件（包括语言模型）</label><label class="inline-check"><input type="checkbox" v-model="keepWorks"/>保留图片、漫画、聊天、词库与个人设置</label><p :class="keepWorks&&keepModels?'info-note':'error-note'">{{keepModels?'模型会保留在原位置。':'本软件内的模型文件将永久删除。'}}{{keepWorks?'创作文件会保留在 works。':'works 中的全部创作和设置将永久删除。'}}程序与独立插件将卸载。</p><div class="button-row"><button class="secondary" :disabled="maintaining" @click="uninstall=false">取消</button><button class="secondary danger" :disabled="maintaining" :aria-busy="maintaining" @click="s.action(()=>maintain('uninstall'))">{{maintaining?'正在卸载…':'卸载并退出软件'}}</button></div></div></section></div></template>
